from django.core.cache import cache
cache.set('number', '123', 60)
try:
    cache.incr('number')
except ValueError:
    print('Not an integer')
else:
    print('Success')

from django.core.cache import cache
cache.set('counter', '100', 60)
try:
    cache.incr('counter', 1)
except ValueError as e:
    print(type(e).__name__)
else:
    print(cache.get('counter'))

